import { Hono } from "hono";
import { z } from "zod";
import type { AppVariables, Env } from "../../../../src/types";
import { requireScope } from "../../../../src/lib/auth";
import { AppError } from "../../../../src/lib/errors";
import { createId } from "../../../../src/lib/ids";
import { createDocument, postDocument, reverseDocument } from "../../../../src/services/documents";
import { createJournal, postJournal, reverseJournal } from "../../../../src/services/ledger";
import { audit, camelizeRow, camelizeRows, date, parseLimit, parseOffset, schoolPermission } from "../common";
import { addDays, adjustmentBuckets, claimBillingGuard, computeAdjustments, createChargeAndInvoice, ensureFeeAccounting, fullName, money, nextNumber, nullableText, postSchoolFeeCharge, provisionCategory, releaseBillingGuard, requireCategory, requirePayer, requireStudent, resolveStructure, studentBalance, today, validateAccount } from "./common";

export const schoolFeeBillingRoutes=new Hono<{Bindings:Env;Variables:AppVariables}>();
schoolFeeBillingRoutes.use("*",requireScope("school:read"));

const billingSchema=z.object({studentId:z.string(),academicYearId:z.string(),termId:z.string().optional().nullable(),structureId:z.string().optional().nullable(),payerContactId:z.string().optional().nullable(),billingDate:date.default(today()),dueDate:date.optional().nullable(),autoPost:z.boolean().optional()});

export async function billStudent(db:D1Database,org:string,actor:string,input:z.infer<typeof billingSchema>,batchId?:string|null,preview=false){
  const student=await requireStudent(db,org,input.studentId);
  const payer=await requirePayer(db,org,student,input.payerContactId);
  const structure=await resolveStructure(db,org,student,input.academicYearId,input.termId,input.structureId);
  const structureId=String(structure.id),currency=String(structure.currency||"UGX");
  const lines=await db.prepare(`SELECT l.*,fc.name AS category_name FROM school_fee_structure_lines l JOIN school_fee_categories fc ON fc.id=l.fee_category_id AND fc.organization_id=l.organization_id WHERE l.organization_id=? AND l.structure_id=? ORDER BY fc.name`).bind(org,structureId).all<any>();
  if(!lines.results.length)throw new AppError(422,"EMPTY_FEE_STRUCTURE","The matching fee structure does not contain any fee items");
  const result:any[]=[];let total=0,skipped=0,billed=0,failed=0;
  for(const line of lines.results){
    const key={studentId:student.id,structureLineId:String(line.id),academicYearId:input.academicYearId,termId:input.termId};
    if(preview){
      const duplicate=await db.prepare(`SELECT g.charge_id AS chargeId,c.status,c.total_minor AS totalMinor,d.number AS invoiceNumber FROM school_fee_billing_guards g LEFT JOIN school_student_fee_charges c ON c.id=g.charge_id AND c.organization_id=g.organization_id LEFT JOIN documents d ON d.id=c.document_id AND d.organization_id=c.organization_id WHERE g.organization_id=? AND g.student_id=? AND g.structure_line_id=? AND g.academic_year_id=? AND g.term_key=?`).bind(org,student.id,line.id,input.academicYearId,input.termId||"").first<any>();
      if(duplicate){result.push({structureLineId:line.id,feeCategoryId:line.fee_category_id,feeCategoryName:line.category_name,status:"skipped",reason:"already_billed",existingChargeId:duplicate.chargeId,invoiceNumber:duplicate.invoiceNumber,totalMinor:duplicate.totalMinor});skipped++;continue;}
    }
    const quantity=Number(line.quantity_micros||1_000_000),gross=Math.round(Number(line.amount_minor)*quantity/1_000_000);
    const adjustments=await computeAdjustments(db,org,student,{academicYearId:input.academicYearId,termId:input.termId,feeCategoryId:line.fee_category_id,grossMinor:gross,discountable:Boolean(line.discountable),chargeDate:input.billingDate});
    const buckets=adjustmentBuckets(adjustments),net=Math.max(0,gross-buckets.totalAdjustmentMinor)+Number(line.tax_minor||0),due=input.dueDate||line.due_date||null;
    if(preview){total+=net;result.push({structureLineId:line.id,feeCategoryId:line.fee_category_id,feeCategoryName:line.category_name,grossMinor:gross,...buckets,taxMinor:Number(line.tax_minor||0),totalMinor:net,dueDate:due,adjustments,status:"ready"});continue;}
    const chargeId=createId("sfc"),guard=await claimBillingGuard(db,org,key,chargeId);
    if(!guard.claimed){result.push({structureLineId:line.id,feeCategoryId:line.fee_category_id,feeCategoryName:line.category_name,status:"skipped",reason:"already_billed",existingChargeId:guard.existing?.chargeId,invoiceNumber:guard.existing?.invoiceNumber,totalMinor:guard.existing?.totalMinor});skipped++;continue;}
    try{
      const created=await createChargeAndInvoice(db,org,actor,{chargeId,student,payerContactId:payer.id,academicYearId:input.academicYearId,termId:input.termId,feeCategoryId:line.fee_category_id,structureLineId:line.id,billingBatchId:batchId,description:line.description||`${line.category_name} — ${fullName(student)}`,quantityMicros:quantity,grossMinor:gross,taxMinor:Number(line.tax_minor||0),taxAccountId:line.tax_account_id,chargeDate:input.billingDate,dueDate:due,source:"structure",currency,adjustments,metadata:{structureId},autoPost:input.autoPost});
      total+=created.totalMinor;billed++;result.push({structureLineId:line.id,feeCategoryId:line.fee_category_id,feeCategoryName:line.category_name,status:"billed",...created});
    }catch(error){
      const persisted=await db.prepare("SELECT id,status,total_minor AS totalMinor,document_id AS documentId FROM school_student_fee_charges WHERE id=? AND organization_id=?").bind(chargeId,org).first<any>();
      if(!persisted)await releaseBillingGuard(db,org,chargeId);else total+=Number(persisted.totalMinor||0);
      failed++;result.push({structureLineId:line.id,feeCategoryId:line.fee_category_id,feeCategoryName:line.category_name,status:"failed",chargeId:persisted?.id||null,chargeStatus:persisted?.status||null,persisted:Boolean(persisted),code:error instanceof AppError?error.code:"BILLING_ERROR",message:error instanceof Error?error.message:String(error),totalMinor:persisted?.totalMinor||0});
    }
  }
  return {student:{id:student.id,name:fullName(student),admissionNumber:student.admissionNumber,studentNumber:student.studentNumber},payer,structure:{id:structureId,code:structure.code,name:structure.name,currency},lines:result,totalMinor:total,billed,skipped,failed};
}

schoolFeeBillingRoutes.post("/billing/preview",schoolPermission("school.fees:read"),async c=>{const p=c.get("principal"),s=billingSchema.safeParse(await c.req.json());if(!s.success)throw new AppError(422,"VALIDATION_ERROR","Invalid fee billing preview request",s.error.flatten());return c.json({data:await billStudent(c.env.FINANCE_DB,p.organizationId,p.userId,s.data,null,true)})});
schoolFeeBillingRoutes.post("/billing/student",requireScope("school:write"),schoolPermission("school.fees:write"),async c=>{const p=c.get("principal"),s=billingSchema.safeParse(await c.req.json());if(!s.success)throw new AppError(422,"VALIDATION_ERROR","Invalid student billing request",s.error.flatten());const data=await billStudent(c.env.FINANCE_DB,p.organizationId,p.userId,s.data);await audit(c.env.FINANCE_DB,c,"school.fees.student.billed","school_student",s.data.studentId,{academicYearId:s.data.academicYearId,termId:s.data.termId,totalMinor:data.totalMinor});return c.json({data},201)});

const billingScheduleSchema=z.object({name:z.string().min(2).max(180),academicYearId:z.string(),termId:z.string().optional().nullable(),structureId:z.string().optional().nullable(),runOn:date,dueDate:date.optional().nullable(),criteria:z.object({campusId:z.string().optional().nullable(),classLevelId:z.string().optional().nullable(),classId:z.string().optional().nullable(),streamId:z.string().optional().nullable(),residencyStatus:z.enum(["day","boarding","hybrid"]).optional().nullable(),studentCategory:z.string().max(100).optional().nullable(),studentIds:z.array(z.string()).max(2000).optional()}).default({}),autoPost:z.boolean().default(true)});
schoolFeeBillingRoutes.get("/billing/schedules",schoolPermission("school.fees:read"),async c=>{const p=c.get("principal"),r=await c.env.FINANCE_DB.prepare("SELECT * FROM school_fee_billing_schedules WHERE organization_id=? ORDER BY run_on DESC,created_at DESC").bind(p.organizationId).all<Record<string,unknown>>();return c.json({data:camelizeRows(r.results)})});
schoolFeeBillingRoutes.post("/billing/schedules",requireScope("school:write"),schoolPermission("school.fees:write"),async c=>{const p=c.get("principal"),s=billingScheduleSchema.safeParse(await c.req.json());if(!s.success)throw new AppError(422,"VALIDATION_ERROR","Invalid automatic fee billing schedule",s.error.flatten());const v=s.data,id=createId("fbs");if(v.dueDate&&v.dueDate<v.runOn)throw new AppError(422,"INVALID_DUE_DATE","Invoice due date cannot be before the scheduled billing date");if(!await c.env.FINANCE_DB.prepare("SELECT 1 FROM school_academic_years WHERE id=? AND organization_id=?").bind(v.academicYearId,p.organizationId).first())throw new AppError(422,"INVALID_ACADEMIC_YEAR","Academic year does not belong to this school");if(v.termId&&!await c.env.FINANCE_DB.prepare("SELECT 1 FROM school_terms WHERE id=? AND organization_id=? AND academic_year_id=?").bind(v.termId,p.organizationId,v.academicYearId).first())throw new AppError(422,"INVALID_TERM","Term does not belong to the selected academic year");if(v.structureId&&!await c.env.FINANCE_DB.prepare("SELECT 1 FROM school_fee_structures WHERE id=? AND organization_id=? AND status='active'").bind(v.structureId,p.organizationId).first())throw new AppError(422,"INVALID_FEE_STRUCTURE","Fee structure must be active");await c.env.FINANCE_DB.prepare("INSERT INTO school_fee_billing_schedules (id,organization_id,name,academic_year_id,term_id,structure_id,run_on,due_date,criteria_json,auto_post,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?)").bind(id,p.organizationId,v.name,v.academicYearId,v.termId??null,v.structureId??null,v.runOn,v.dueDate??null,JSON.stringify(v.criteria),v.autoPost?1:0,p.userId).run();return c.json({data:{id,status:"pending",...v}},201)});
schoolFeeBillingRoutes.delete("/billing/schedules/:id",requireScope("school:write"),schoolPermission("school.fees:write"),async c=>{const p=c.get("principal"),id=c.req.param("id"),r=await c.env.FINANCE_DB.prepare("UPDATE school_fee_billing_schedules SET status='cancelled',updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=? AND status='pending'").bind(id,p.organizationId).run();if(!r.meta.changes)throw new AppError(409,"BILLING_SCHEDULE_NOT_PENDING","Only a pending automatic billing schedule can be cancelled");return c.json({data:{id,status:"cancelled"}})});

const bulkSchema=z.object({academicYearId:z.string(),termId:z.string().optional().nullable(),structureId:z.string().optional().nullable(),campusId:z.string().optional().nullable(),classLevelId:z.string().optional().nullable(),classId:z.string().optional().nullable(),streamId:z.string().optional().nullable(),residencyStatus:z.enum(["day","boarding","hybrid"]).optional().nullable(),studentCategory:z.string().max(100).optional().nullable(),studentIds:z.array(z.string()).max(2000).optional(),billingDate:date.default(today()),dueDate:date.optional().nullable(),autoPost:z.boolean().optional(),idempotencyKey:z.string().min(8).max(200)});
schoolFeeBillingRoutes.post("/billing/bulk",requireScope("school:write"),schoolPermission("school.fees:write"),async c=>{
  const p=c.get("principal"),parsed=bulkSchema.safeParse(await c.req.json());
  if(!parsed.success)throw new AppError(422,"VALIDATION_ERROR","Invalid bulk fee billing request",parsed.error.flatten());
  const v=parsed.data,existing=await c.env.FINANCE_DB.prepare("SELECT * FROM school_fee_billing_batches WHERE organization_id=? AND idempotency_key=?").bind(p.organizationId,v.idempotencyKey).first<Record<string,unknown>>();
  if(existing){const rr=await c.env.FINANCE_DB.prepare(`SELECT br.*,s.admission_number,s.student_number,TRIM(s.first_name||' '||COALESCE(s.middle_name||' ','')||s.last_name) AS student_name FROM school_fee_billing_batch_results br JOIN school_students s ON s.id=br.student_id AND s.organization_id=br.organization_id WHERE br.organization_id=? AND br.batch_id=? ORDER BY s.last_name,s.first_name`).bind(p.organizationId,String((existing as any).id)).all<any>();return c.json({data:{...camelizeRow(existing),results:camelizeRows(rr.results)}});}
  const filters=["s.organization_id=?","s.deleted_at IS NULL","s.status='active'"],bind:any[]=[p.organizationId];
  if(v.campusId){filters.push("s.campus_id=?");bind.push(v.campusId)}if(v.classId){filters.push("s.current_class_id=?");bind.push(v.classId)}if(v.streamId){filters.push("s.current_stream_id=?");bind.push(v.streamId)}if(v.residencyStatus){filters.push("s.residency_status=?");bind.push(v.residencyStatus)}if(v.studentCategory){filters.push("s.student_category=?");bind.push(v.studentCategory)}if(v.classLevelId){filters.push("EXISTS(SELECT 1 FROM school_classes cl WHERE cl.id=s.current_class_id AND cl.organization_id=s.organization_id AND cl.class_level_id=?)");bind.push(v.classLevelId)}if(v.studentIds?.length){filters.push(`s.id IN (${v.studentIds.map(()=>"?").join(",")})`);bind.push(...v.studentIds)}
  const students=await c.env.FINANCE_DB.prepare(`SELECT s.id,s.admission_number AS admissionNumber,s.student_number AS studentNumber,TRIM(s.first_name||' '||COALESCE(s.middle_name||' ','')||s.last_name) AS studentName FROM school_students s WHERE ${filters.join(" AND ")} ORDER BY s.last_name,s.first_name`).bind(...bind).all<any>();
  if(!students.results.length)throw new AppError(422,"NO_STUDENTS_MATCH","No active students match the selected billing criteria");
  const batchId=createId("fbt"),batchNumber=await nextNumber(c.env.FINANCE_DB,p.organizationId,"fee_batch","FB-"),criteria={campusId:v.campusId,classLevelId:v.classLevelId,classId:v.classId,streamId:v.streamId,residencyStatus:v.residencyStatus,studentCategory:v.studentCategory,studentIds:v.studentIds};
  await c.env.FINANCE_DB.prepare(`INSERT INTO school_fee_billing_batches (id,organization_id,batch_number,academic_year_id,term_id,structure_id,billing_date,due_date,criteria_json,status,total_students,idempotency_key,created_by) VALUES (?,?,?,?,?,?,?,?,?,'processing',?,?,?)`).bind(batchId,p.organizationId,batchNumber,v.academicYearId,v.termId??null,v.structureId??null,v.billingDate,v.dueDate??null,JSON.stringify(criteria),students.results.length,v.idempotencyKey,p.userId).run();
  const work=students.results.slice(),results:any[]=[];let cursor=0;
  async function worker(){while(true){const i=cursor++;if(i>=work.length)return;const st=work[i]!;try{const r=await billStudent(c.env.FINANCE_DB,p.organizationId,p.userId,{studentId:st.id,academicYearId:v.academicYearId,termId:v.termId,structureId:v.structureId,billingDate:v.billingDate,dueDate:v.dueDate,autoPost:v.autoPost},batchId,false);const outcome=r.billed>0?(r.failed>0?"partial":"billed"):(r.failed>0?"failed":"skipped");results[i]={studentId:st.id,studentName:st.studentName,admissionNumber:st.admissionNumber,studentNumber:st.studentNumber,outcome,billedItems:r.billed,skippedItems:r.skipped,failedItems:r.failed,totalAmountMinor:r.totalMinor,code:r.failed?"ITEM_FAILURES":r.skipped&&!r.billed?"ALREADY_BILLED":null,message:r.failed?`${r.failed} fee item(s) failed`:r.skipped&&!r.billed?"All matching fee items were already billed":null,details:{lines:r.lines}};}catch(error){results[i]={studentId:st.id,studentName:st.studentName,admissionNumber:st.admissionNumber,studentNumber:st.studentNumber,outcome:"failed",billedItems:0,skippedItems:0,failedItems:1,totalAmountMinor:0,code:error instanceof AppError?error.code:"BILLING_ERROR",message:error instanceof Error?error.message:String(error),details:{}};}}}
  await Promise.all(Array.from({length:Math.min(4,work.length)},()=>worker()));
  for(let i=0;i<results.length;i+=50){await c.env.FINANCE_DB.batch(results.slice(i,i+50).map(r=>c.env.FINANCE_DB.prepare(`INSERT INTO school_fee_billing_batch_results (id,organization_id,batch_id,student_id,outcome,billed_items,skipped_items,failed_items,total_amount_minor,code,message,details_json) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`).bind(createId("fbr"),p.organizationId,batchId,r.studentId,r.outcome,r.billedItems,r.skippedItems,r.failedItems,r.totalAmountMinor,r.code,r.message,JSON.stringify(r.details||{}))));}
  const billed=results.filter(r=>r.outcome==="billed"||r.outcome==="partial").length,failed=results.filter(r=>r.outcome==="failed"||r.outcome==="partial").length,skipped=results.filter(r=>r.outcome==="skipped").length,total=results.reduce((n,r)=>n+Number(r.totalAmountMinor||0),0),status=failed===0?"completed":billed>0?"partial":"failed";
  await c.env.FINANCE_DB.prepare("UPDATE school_fee_billing_batches SET status=?,billed_students=?,failed_students=?,total_amount_minor=?,errors_json=?,completed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?").bind(status,billed,failed,total,JSON.stringify(results.filter(r=>r.outcome==="failed"||r.outcome==="partial").slice(0,500).map(r=>({studentId:r.studentId,code:r.code,message:r.message}))),batchId,p.organizationId).run();
  await audit(c.env.FINANCE_DB,c,"school.fees.bulk_billed","school_fee_billing_batch",batchId,{billed,failed,skipped,totalMinor:total});
  return c.json({data:{id:batchId,batchNumber,status,totalStudents:students.results.length,billedStudents:billed,failedStudents:failed,skippedStudents:skipped,totalAmountMinor:total,results}},201);
});

schoolFeeBillingRoutes.get("/billing/batches",schoolPermission("school.fees:read"),async c=>{const p=c.get("principal"),rows=await c.env.FINANCE_DB.prepare("SELECT * FROM school_fee_billing_batches WHERE organization_id=? ORDER BY created_at DESC LIMIT ? OFFSET ?").bind(p.organizationId,parseLimit(c),parseOffset(c)).all<Record<string,unknown>>();return c.json({data:camelizeRows(rows.results)})});
schoolFeeBillingRoutes.get("/billing/batches/:id/results",schoolPermission("school.fees:read"),async c=>{const p=c.get("principal"),id=c.req.param("id"),batch=await c.env.FINANCE_DB.prepare("SELECT * FROM school_fee_billing_batches WHERE id=? AND organization_id=?").bind(id,p.organizationId).first<Record<string,unknown>>();if(!batch)throw new AppError(404,"BILLING_BATCH_NOT_FOUND","Billing batch not found");const rows=await c.env.FINANCE_DB.prepare(`SELECT br.*,s.admission_number,s.student_number,TRIM(s.first_name||' '||COALESCE(s.middle_name||' ','')||s.last_name) AS student_name FROM school_fee_billing_batch_results br JOIN school_students s ON s.id=br.student_id AND s.organization_id=br.organization_id WHERE br.organization_id=? AND br.batch_id=? ORDER BY CASE br.outcome WHEN 'failed' THEN 0 WHEN 'partial' THEN 1 WHEN 'skipped' THEN 2 ELSE 3 END,s.last_name,s.first_name`).bind(p.organizationId,id).all<Record<string,unknown>>();return c.json({data:{batch:camelizeRow(batch),results:camelizeRows(rows.results)}})});

const manualChargeSchema=z.object({studentId:z.string(),payerContactId:z.string().optional().nullable(),academicYearId:z.string().optional().nullable(),termId:z.string().optional().nullable(),feeCategoryId:z.string(),description:z.string().trim().min(2).max(1000),amountMinor:z.number().int().positive(),taxMinor:money.default(0),taxAccountId:z.string().optional().nullable(),chargeDate:date.default(today()),dueDate:date.optional().nullable(),currency:z.string().length(3).toUpperCase().optional(),discountMinor:money.default(0),scholarshipMinor:money.default(0),waiverMinor:money.default(0),autoPost:z.boolean().optional(),metadata:z.record(z.string(),z.unknown()).default({})});
schoolFeeBillingRoutes.post("/charges/manual",requireScope("school:write"),schoolPermission("school.fees:write"),async c=>{const p=c.get("principal"),s=manualChargeSchema.safeParse(await c.req.json());if(!s.success)throw new AppError(422,"VALIDATION_ERROR","Invalid manual fee charge",s.error.flatten());const v=s.data,student=await requireStudent(c.env.FINANCE_DB,p.organizationId,v.studentId),payer=await requirePayer(c.env.FINANCE_DB,p.organizationId,student,v.payerContactId),defaults=await ensureFeeAccounting(c.env.FINANCE_DB,p.organizationId);const totalAdjust=v.discountMinor+v.scholarshipMinor+v.waiverMinor;if(totalAdjust>v.amountMinor)throw new AppError(422,"ADJUSTMENT_EXCEEDS_CHARGE","Discounts, scholarships and waivers cannot exceed the fee amount");const adjustments=[] as any[];if(v.discountMinor)adjustments.push({type:"discount",amountMinor:v.discountMinor,reason:"Manual discount",accountingTreatment:"net_revenue"});if(v.scholarshipMinor)adjustments.push({type:"scholarship",amountMinor:v.scholarshipMinor,reason:"Manual scholarship",accountingTreatment:"net_revenue"});if(v.waiverMinor)adjustments.push({type:"waiver",amountMinor:v.waiverMinor,reason:"Manual waiver",accountingTreatment:"net_revenue"});const data=await createChargeAndInvoice(c.env.FINANCE_DB,p.organizationId,p.userId,{student,payerContactId:payer.id,academicYearId:v.academicYearId??student.currentAcademicYearId,termId:v.termId,feeCategoryId:v.feeCategoryId,description:v.description,quantityMicros:1_000_000,grossMinor:v.amountMinor,taxMinor:v.taxMinor,taxAccountId:v.taxAccountId,chargeDate:v.chargeDate,dueDate:v.dueDate,source:"manual",currency:v.currency||defaults.defaultCurrency,adjustments,metadata:v.metadata,autoPost:v.autoPost});await audit(c.env.FINANCE_DB,c,"school.fees.charge.created","school_fee_charge",data.chargeId,v);return c.json({data},201)});

schoolFeeBillingRoutes.get("/charges",schoolPermission("school.fees:read"),async c=>{const p=c.get("principal"),filters=["c.organization_id=?"],bind:any[]=[p.organizationId],studentId=c.req.query("studentId"),year=c.req.query("academicYearId"),term=c.req.query("termId"),status=c.req.query("status"),payer=c.req.query("payerContactId");if(studentId){filters.push("c.student_id=?");bind.push(studentId)}if(year){filters.push("c.academic_year_id=?");bind.push(year)}if(term){filters.push("c.term_id=?");bind.push(term)}if(status){if(status==="reversed")filters.push("rev.id IS NOT NULL");else{filters.push("c.status=?");bind.push(status)}}if(payer){filters.push("c.payer_contact_id=?");bind.push(payer)}const rows=await c.env.FINANCE_DB.prepare(`SELECT c.*,s.admission_number,s.student_number,s.first_name||' '||COALESCE(s.middle_name||' ','')||s.last_name AS student_name,fc.code AS fee_category_code,fc.name AS fee_category_name,ct.name AS payer_name,d.number AS invoice_number,d.paid_minor,d.status AS document_status,rev.id AS reversal_id,rev.reason AS reversal_reason,rev.reversed_at FROM school_student_fee_charges c JOIN school_students s ON s.id=c.student_id JOIN school_fee_categories fc ON fc.id=c.fee_category_id JOIN contacts ct ON ct.id=c.payer_contact_id LEFT JOIN documents d ON d.id=c.document_id LEFT JOIN school_fee_charge_reversals rev ON rev.charge_id=c.id AND rev.organization_id=c.organization_id WHERE ${filters.join(" AND ")} ORDER BY c.charge_date DESC,c.created_at DESC LIMIT ? OFFSET ?`).bind(...bind,parseLimit(c),parseOffset(c)).all<Record<string,unknown>>();return c.json({data:camelizeRows(rows.results).map((r:any)=>({...r,status:r.reversalId?"reversed":r.status}))})});
schoolFeeBillingRoutes.get("/charges/:id",schoolPermission("school.fees:read"),async c=>{const p=c.get("principal"),id=c.req.param("id"),row=await c.env.FINANCE_DB.prepare(`SELECT c.*,s.admission_number,s.student_number,s.first_name||' '||COALESCE(s.middle_name||' ','')||s.last_name AS student_name,fc.name AS fee_category_name,ct.name AS payer_name,d.number AS invoice_number,d.status AS document_status,d.paid_minor,rev.id AS reversal_id,rev.reason AS reversal_reason,rev.reversed_at FROM school_student_fee_charges c JOIN school_students s ON s.id=c.student_id JOIN school_fee_categories fc ON fc.id=c.fee_category_id JOIN contacts ct ON ct.id=c.payer_contact_id LEFT JOIN documents d ON d.id=c.document_id LEFT JOIN school_fee_charge_reversals rev ON rev.charge_id=c.id AND rev.organization_id=c.organization_id WHERE c.id=? AND c.organization_id=?`).bind(id,p.organizationId).first<Record<string,unknown>>();if(!row)throw new AppError(404,"FEE_CHARGE_NOT_FOUND","School fee charge not found");const [adjustments,credits,writeoffs]=await Promise.all([c.env.FINANCE_DB.prepare("SELECT * FROM school_fee_charge_adjustments WHERE charge_id=? AND organization_id=? ORDER BY created_at").bind(id,p.organizationId).all<Record<string,unknown>>(),c.env.FINANCE_DB.prepare("SELECT id,credit_number,amount_minor,credit_date,reason,status,reversed_at,created_at FROM school_fee_credits WHERE charge_id=? AND organization_id=? ORDER BY created_at DESC").bind(id,p.organizationId).all<Record<string,unknown>>(),c.env.FINANCE_DB.prepare("SELECT id,writeoff_number,amount_minor,writeoff_date,reason,status,reversed_at,created_at FROM school_fee_writeoffs WHERE charge_id=? AND organization_id=? ORDER BY created_at DESC").bind(id,p.organizationId).all<Record<string,unknown>>()]);const base:any=camelizeRow(row);if(base.reversalId)base.status="reversed";return c.json({data:{...base,adjustments:camelizeRows(adjustments.results),credits:camelizeRows(credits.results),writeoffs:camelizeRows(writeoffs.results)}})});

async function reverseFeeCharge(db:D1Database,org:string,actor:string,chargeId:string,postingDate:string,reason:string,reversalBatchId?:string|null){
  const existing=await db.prepare("SELECT id,reversal_kind AS reversalKind,reversal_journal_id AS reversalJournalId,reversed_at AS reversedAt FROM school_fee_charge_reversals WHERE organization_id=? AND charge_id=?").bind(org,chargeId).first<any>();
  if(existing)return {id:chargeId,status:"reversed",reversalId:existing.id,reversalKind:existing.reversalKind,reversalJournalId:existing.reversalJournalId,reversedAt:existing.reversedAt,alreadyReversed:true};
  const charge=await db.prepare(`SELECT c.*,d.status AS documentStatus,d.paid_minor AS documentPaidMinor,d.journal_entry_id AS journalEntryId FROM school_student_fee_charges c LEFT JOIN documents d ON d.id=c.document_id AND d.organization_id=c.organization_id WHERE c.id=? AND c.organization_id=?`).bind(chargeId,org).first<any>();
  if(!charge)throw new AppError(404,"FEE_CHARGE_NOT_FOUND","School fee charge not found");
  if(charge.status==="cancelled")throw new AppError(409,"CHARGE_ALREADY_CANCELLED","This fee charge is already cancelled");
  const settlements=await db.prepare(`SELECT
    (SELECT COALESCE(SUM(pa.amount_minor),0) FROM payment_allocations pa WHERE pa.organization_id=? AND pa.document_id=? AND pa.reversed_at IS NULL) AS paymentMinor,
    (SELECT COALESCE(SUM(amount_minor),0) FROM school_fee_credits WHERE organization_id=? AND charge_id=? AND status='posted') AS creditMinor,
    (SELECT COALESCE(SUM(amount_minor),0) FROM school_fee_writeoffs WHERE organization_id=? AND charge_id=? AND status='posted') AS writeoffMinor`).bind(org,charge.document_id,org,chargeId,org,chargeId).first<any>();
  if(Number(settlements?.paymentMinor||0)>0||Number(settlements?.creditMinor||0)>0||Number(settlements?.writeoffMinor||0)>0)throw new AppError(409,"CHARGE_HAS_SETTLEMENTS","Reverse payments, credits and write-offs before reversing this fee billing",settlements);
  const reversedAdjustmentJournals:string[]=[];
  const adjustments=await db.prepare(`SELECT a.journal_entry_id AS journalEntryId,j.status FROM school_fee_charge_adjustments a LEFT JOIN journal_entries j ON j.id=a.journal_entry_id AND j.organization_id=a.organization_id WHERE a.organization_id=? AND a.charge_id=? AND a.journal_entry_id IS NOT NULL`).bind(org,chargeId).all<any>();
  for(const a of adjustments.results){if(a.status==="posted"){const rr=await reverseJournal(db,org,actor,a.journalEntryId,postingDate,reason);reversedAdjustmentJournals.push(rr.id)}else if(a.status==="reversed")reversedAdjustmentJournals.push(a.journalEntryId);}
  let kind:"posted_reversal"|"draft_void"="draft_void",reversalJournalId:string|null=null;
  if(charge.document_id){
    if(charge.documentStatus==="draft"){await db.prepare("DELETE FROM documents WHERE id=? AND organization_id=? AND status='draft'").bind(charge.document_id,org).run();}
    else if(["open","partially_paid","paid"].includes(charge.documentStatus)){const rr=await reverseDocument(db,org,actor,charge.document_id,postingDate,reason);kind="posted_reversal";reversalJournalId=rr.reversalJournalId;}
    else if(charge.documentStatus==="void"){kind="posted_reversal";}
  }
  const reversalId=createId("frr");
  await db.batch([db.prepare(`INSERT INTO school_fee_charge_reversals (id,organization_id,charge_id,reversal_batch_id,posting_date,reason,reversal_kind,reversal_journal_id,reversed_by,metadata_json) VALUES (?,?,?,?,?,?,?,?,?,?)`).bind(reversalId,org,chargeId,reversalBatchId??null,postingDate,reason,kind,reversalJournalId,actor,JSON.stringify({reversedAdjustmentJournals})),db.prepare("UPDATE school_student_fee_charges SET status='cancelled',updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?").bind(chargeId,org)]);
  await releaseBillingGuard(db,org,chargeId);
  return {id:chargeId,status:"reversed",reversalId,reversalKind:kind,reversalJournalId};
}

schoolFeeBillingRoutes.post("/charges/:id/post",requireScope("school:write"),schoolPermission("school.fees:approve"),async c=>{const p=c.get("principal"),id=c.req.param("id"),data=await postSchoolFeeCharge(c.env.FINANCE_DB,p.organizationId,p.userId,id);await audit(c.env.FINANCE_DB,c,"school.fees.charge.posted","school_fee_charge",id,{documentId:data.documentId,journalEntryId:data.journalEntryId});return c.json({data})});

const reversalSchema=z.object({postingDate:date.default(today()),reason:z.string().trim().min(3).max(1000)});
