schoolFeeBillingRoutes.post("/charges/reverse-bulk",requireScope("school:write"),schoolPermission("school.fees:approve"),async c=>{const p=c.get("principal"),parsed=z.object({chargeIds:z.array(z.string()).min(1).max(500),postingDate:date.default(today()),reason:z.string().trim().min(3).max(1000)}).safeParse(await c.req.json());if(!parsed.success)throw new AppError(422,"VALIDATION_ERROR","Select up to 500 fee charges and provide a reversal reason",parsed.error.flatten());const batchId=createId("frb"),results:any[]=[];for(const chargeId of [...new Set(parsed.data.chargeIds)]){try{const r=await reverseFeeCharge(c.env.FINANCE_DB,p.organizationId,p.userId,chargeId,parsed.data.postingDate,parsed.data.reason,batchId);results.push({chargeId,status:"reversed",...r})}catch(error){results.push({chargeId,status:"failed",code:error instanceof AppError?error.code:"REVERSAL_ERROR",message:error instanceof Error?error.message:String(error)})}}const reversed=results.filter(r=>r.status==="reversed").length,failed=results.length-reversed;await audit(c.env.FINANCE_DB,c,"school.fees.bulk_reversed","school_fee_reversal_batch",batchId,{reversed,failed,reason:parsed.data.reason});return c.json({data:{id:batchId,total:results.length,reversed,failed,status:failed?reversed?"partial":"failed":"completed",results}})});

schoolFeeBillingRoutes.post("/billing/batches/:id/reverse",requireScope("school:write"),schoolPermission("school.fees:approve"),async c=>{const p=c.get("principal"),batchId=c.req.param("id"),parsed=reversalSchema.safeParse(await c.req.json());if(!parsed.success)throw new AppError(422,"VALIDATION_ERROR","Provide a reversal reason",parsed.error.flatten());const charges=await c.env.FINANCE_DB.prepare("SELECT id FROM school_student_fee_charges WHERE organization_id=? AND billing_batch_id=? AND status<>'cancelled' ORDER BY created_at LIMIT 501").bind(p.organizationId,batchId).all<{id:string}>();if(charges.results.length>500)throw new AppError(422,"REVERSAL_BATCH_TOO_LARGE","This billing batch contains more than 500 active fee items. Reverse it in selected groups of up to 500 items.");if(!charges.results.length)throw new AppError(409,"NO_ACTIVE_BILLINGS","This billing batch has no active fee charges to reverse");const reversalBatchId=createId("frb"),results:any[]=[];for(const row of charges.results){try{results.push({chargeId:row.id,status:"reversed",...await reverseFeeCharge(c.env.FINANCE_DB,p.organizationId,p.userId,row.id,parsed.data.postingDate,parsed.data.reason,reversalBatchId)})}catch(error){results.push({chargeId:row.id,status:"failed",code:error instanceof AppError?error.code:"REVERSAL_ERROR",message:error instanceof Error?error.message:String(error)})}}const reversed=results.filter(r=>r.status==="reversed").length,failed=results.length-reversed,status=failed?(reversed?"partial":"failed"):"completed";await c.env.FINANCE_DB.prepare("UPDATE school_fee_billing_batches SET status=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?").bind(status==="completed"?"cancelled":status,batchId,p.organizationId).run();await audit(c.env.FINANCE_DB,c,"school.fees.billing_batch.reversed","school_fee_billing_batch",batchId,{reversalBatchId,reversed,failed,reason:parsed.data.reason});return c.json({data:{id:reversalBatchId,billingBatchId:batchId,total:results.length,reversed,failed,status,results}})});

schoolFeeBillingRoutes.post("/charges/:id/cancel",requireScope("school:write"),schoolPermission("school.fees:approve"),async c=>{const p=c.get("principal"),id=c.req.param("id"),parsed=reversalSchema.safeParse(await c.req.json());if(!parsed.success)throw new AppError(422,"VALIDATION_ERROR","Provide a reversal reason",parsed.error.flatten());const data=await reverseFeeCharge(c.env.FINANCE_DB,p.organizationId,p.userId,id,parsed.data.postingDate,parsed.data.reason);return c.json({data})});

async function settleInvoiceBalance(db:D1Database,org:string,documentId:string,amount:number){const d=await db.prepare("SELECT total_minor AS totalMinor,paid_minor AS paidMinor FROM documents WHERE id=? AND organization_id=?").bind(documentId,org).first<{totalMinor:number;paidMinor:number}>();if(!d)throw new AppError(409,"FEE_INVOICE_MISSING","The Ledgerly invoice linked to this fee charge is missing");const next=Math.min(d.totalMinor,d.paidMinor+amount);await db.prepare("UPDATE documents SET paid_minor=?,status=CASE WHEN ?=total_minor THEN 'paid' ELSE 'partially_paid' END,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?").bind(next,next,documentId,org).run();return next}

schoolFeeBillingRoutes.post("/charges/:id/credit",requireScope("school:write"),schoolPermission("school.fees:approve"),async c=>{const p=c.get("principal"),id=c.req.param("id"),s=z.object({amountMinor:z.number().int().positive(),reason:z.string().min(3).max(1000),creditDate:date.default(today())}).safeParse(await c.req.json());if(!s.success)throw new AppError(422,"VALIDATION_ERROR","Invalid fee credit",s.error.flatten());const ch=await c.env.FINANCE_DB.prepare(`SELECT c.*,fc.income_account_id AS incomeAccountId,fc.product_id AS productId,d.total_minor AS documentTotal,(SELECT COALESCE(SUM(pa.amount_minor),0) FROM payment_allocations pa WHERE pa.organization_id=c.organization_id AND pa.document_id=c.document_id AND pa.reversed_at IS NULL) AS paidMinor FROM school_student_fee_charges c JOIN school_fee_categories fc ON fc.id=c.fee_category_id LEFT JOIN documents d ON d.id=c.document_id WHERE c.id=? AND c.organization_id=?`).bind(id,p.organizationId).first<any>();if(!ch||!ch.document_id)throw new AppError(404,"FEE_CHARGE_NOT_FOUND","Invoiced fee charge not found");const available=Number(ch.total_minor)-Number(ch.credited_minor)-Number(ch.written_off_minor)-Number(ch.paidMinor||0);if(s.data.amountMinor>available)throw new AppError(422,"CREDIT_EXCEEDS_BALANCE","Credit amount cannot exceed the unpaid fee balance",{availableMinor:available});const cat=await provisionCategory(c.env.FINANCE_DB,p.organizationId,ch.fee_category_id),defaults=await ensureFeeAccounting(c.env.FINANCE_DB,p.organizationId),number=await nextNumber(c.env.FINANCE_DB,p.organizationId,"fee_credit","SCN-"),doc=await createDocument(c.env.FINANCE_DB,p.organizationId,p.userId,{type:"credit_note",number,contactId:ch.payer_contact_id,issueDate:s.data.creditDate,dueDate:s.data.creditDate,currency:ch.currency,customFields:{schoolFee:true,studentId:ch.student_id,chargeId:id,creditReason:s.data.reason},lines:[{productId:cat.productId??undefined,accountId:cat.incomeAccountId!,description:`Credit: ${ch.description} — ${s.data.reason}`,quantityMicros:1_000_000,unitPriceMinor:s.data.amountMinor,taxMinor:0,dimensions:{schoolStudentId:ch.student_id,schoolAcademicYearId:ch.academic_year_id,schoolTermId:ch.term_id,schoolFeeCategoryId:ch.fee_category_id}}]});await postDocument(c.env.FINANCE_DB,p.organizationId,p.userId,doc.id,defaults.receivableAccountId);await c.env.FINANCE_DB.prepare("UPDATE documents SET paid_minor=total_minor,status='paid',updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?").bind(doc.id,p.organizationId).run();await settleInvoiceBalance(c.env.FINANCE_DB,p.organizationId,ch.document_id,s.data.amountMinor);const credited=Number(ch.credited_minor)+s.data.amountMinor,status=credited+Number(ch.written_off_minor)+Number(ch.paidMinor||0)>=Number(ch.total_minor)?"credited":ch.status,creditId=createId("fcr");await c.env.FINANCE_DB.batch([c.env.FINANCE_DB.prepare("INSERT INTO school_fee_credits (id,organization_id,credit_number,student_id,charge_id,payer_contact_id,amount_minor,credit_date,currency,reason,document_id,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)").bind(creditId,p.organizationId,number,ch.student_id,id,ch.payer_contact_id,s.data.amountMinor,s.data.creditDate,ch.currency,s.data.reason,doc.id,p.userId),c.env.FINANCE_DB.prepare("UPDATE school_student_fee_charges SET credited_minor=?,credit_document_id=?,status=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND organization_id=?").bind(credited,doc.id,status,id,p.organizationId)]);await audit(c.env.FINANCE_DB,c,"school.fees.charge.credited","school_fee_charge",id,{amountMinor:s.data.amountMinor,creditId,creditDocumentId:doc.id,reason:s.data.reason});return c.json({data:{id:creditId,chargeId:id,creditDocumentId:doc.id,creditNumber:number,creditedMinor:credited}})});

