schoolFeeBillingRoutes.post("/late-fees/assess",requireScope("school:write"),schoolPermission("school.fees:write"),async c=>{const p=c.get("principal"),s=z.object({asOfDate:date.default(today()),dryRun:z.boolean().default(false),studentId:z.string().optional(),limit:z.number().int().min(1).max(1000).default(500)}).safeParse(await c.req.json());if(!s.success)throw new AppError(422,"VALIDATION_ERROR","Invalid late-fee assessment request",s.error.flatten());const v=s.data,filters=["c.organization_id=?","c.status IN ('invoiced','partially_settled')","c.due_date IS NOT NULL","c.due_date<?"],bind:any[]=[p.organizationId,v.asOfDate];if(v.studentId){filters.push("c.student_id=?");bind.push(v.studentId)}const charges=await c.env.FINANCE_DB.prepare(`SELECT c.*,(SELECT COALESCE(SUM(pa.amount_minor),0) FROM payment_allocations pa WHERE pa.organization_id=c.organization_id AND pa.document_id=c.document_id AND pa.reversed_at IS NULL) AS paidMinor FROM school_student_fee_charges c JOIN documents d ON d.id=c.document_id AND d.organization_id=c.organization_id WHERE ${filters.join(" AND ")} ORDER BY c.due_date LIMIT ?`).bind(...bind,v.limit).all<any>();let assessed=0,total=0;const items:any[]=[];for(const ch of charges.results){const outstanding=Math.max(0,Number(ch.total_minor)-Number(ch.paidMinor||0)-Number(ch.credited_minor||0)-Number(ch.written_off_minor||0));if(!outstanding)continue;const rules=await c.env.FINANCE_DB.prepare(`SELECT * FROM school_fee_late_fee_rules WHERE organization_id=? AND active=1 AND (applies_to_fee_category_id IS NULL OR applies_to_fee_category_id=?) AND (starts_on IS NULL OR starts_on<=?) AND (ends_on IS NULL OR ends_on>=?)`).bind(p.organizationId,ch.fee_category_id,v.asOfDate,v.asOfDate).all<any>();for(const rule of rules.results){const due=new Date(`${ch.due_date}T00:00:00Z`),asof=new Date(`${v.asOfDate}T00:00:00Z`),days=Math.floor((asof.getTime()-due.getTime())/86400000);if(days<=Number(rule.grace_days||0))continue;const interval=rule.recurrence==="daily"?1:rule.recurrence==="weekly"?7:rule.recurrence==="monthly"?30:999999,cycle=rule.recurrence==="one_time"?1:Math.max(1,Math.floor((days-Number(rule.grace_days||0))/interval)),key=`${rule.id}:${ch.id}:${rule.recurrence==="one_time"?"once":cycle}`;if(await c.env.FINANCE_DB.prepare("SELECT 1 FROM school_fee_late_fee_assessments WHERE organization_id=? AND assessment_key=?").bind(p.organizationId,key).first())continue;let amount=rule.calculation_type==="fixed"?Number(rule.amount_minor||0):Math.round(outstanding*Number(rule.rate_micros||0)/100_000_000);if(rule.max_amount_minor!=null)amount=Math.min(amount,Number(rule.max_amount_minor));if(amount<=0)continue;items.push({sourceChargeId:ch.id,ruleId:rule.id,ruleName:rule.name,amountMinor:amount,assessmentKey:key});total+=amount;if(v.dryRun)continue;const student=await requireStudent(c.env.FINANCE_DB,p.organizationId,ch.student_id),created=await createChargeAndInvoice(c.env.FINANCE_DB,p.organizationId,p.userId,{student,payerContactId:ch.payer_contact_id,academicYearId:ch.academic_year_id,termId:ch.term_id,feeCategoryId:rule.penalty_fee_category_id,parentChargeId:ch.id,description:`${rule.name} — ${ch.description}`,quantityMicros:1_000_000,grossMinor:amount,chargeDate:v.asOfDate,dueDate:v.asOfDate,source:"late_fee",currency:ch.currency,metadata:{lateFeeRuleId:rule.id,sourceChargeId:ch.id}});await c.env.FINANCE_DB.prepare(`INSERT INTO school_fee_late_fee_assessments (id,organization_id,rule_id,source_charge_id,penalty_charge_id,assessment_key,assessed_on,amount_minor,created_by) VALUES (?,?,?,?,?,?,?,?,?)`).bind(createId("fla"),p.organizationId,rule.id,ch.id,created.chargeId,key,v.asOfDate,amount,p.userId).run();assessed++}}
return c.json({data:{dryRun:v.dryRun,eligible:items.length,assessed:v.dryRun?0:assessed,totalAmountMinor:total,items}})});

