schoolFeeBillingRoutes.get("/students/:studentId/summary",schoolPermission("school.fees:read"),async c=>{const p=c.get("principal"),student=await requireStudent(c.env.FINANCE_DB,p.organizationId,c.req.param("studentId")),balance=await studentBalance(c.env.FINANCE_DB,p.organizationId,student.id,c.req.query("academicYearId"),c.req.query("termId"));return c.json({data:{student,balance}})});

export async function runScheduledFeeBilling(db:D1Database,asOfDate=today()){
  const due=await db.prepare("SELECT * FROM school_fee_billing_schedules WHERE status='pending' AND run_on<=? ORDER BY run_on,created_at LIMIT 20").bind(asOfDate).all<any>();
  for(const schedule of due.results){
    await db.prepare("UPDATE school_fee_billing_schedules SET status='running',updated_at=CURRENT_TIMESTAMP WHERE id=? AND status='pending'").bind(schedule.id).run();
    try{
      const criteria=JSON.parse(schedule.criteria_json||"{}") as any, filters=["s.organization_id=?","s.deleted_at IS NULL","s.status='active'"],bind:any[]=[schedule.organization_id];
      if(criteria.campusId){filters.push("s.campus_id=?");bind.push(criteria.campusId)}if(criteria.classId){filters.push("s.current_class_id=?");bind.push(criteria.classId)}if(criteria.streamId){filters.push("s.current_stream_id=?");bind.push(criteria.streamId)}if(criteria.residencyStatus){filters.push("s.residency_status=?");bind.push(criteria.residencyStatus)}if(criteria.studentCategory){filters.push("s.student_category=?");bind.push(criteria.studentCategory)}if(criteria.classLevelId){filters.push("EXISTS(SELECT 1 FROM school_classes cl WHERE cl.id=s.current_class_id AND cl.organization_id=s.organization_id AND cl.class_level_id=?)");bind.push(criteria.classLevelId)}if(criteria.studentIds?.length){filters.push(`s.id IN (${criteria.studentIds.map(()=>"?").join(",")})`);bind.push(...criteria.studentIds)}
      const students=await db.prepare(`SELECT s.id FROM school_students s WHERE ${filters.join(" AND ")} ORDER BY s.id`).bind(...bind).all<{id:string}>(), batchId=createId("fbt"),batchNumber=await nextNumber(db,schedule.organization_id,"fee_batch","FB-"),idem=`schedule:${schedule.id}:${schedule.run_on}`;
      const previous=await db.prepare("SELECT id FROM school_fee_billing_batches WHERE organization_id=? AND idempotency_key=?").bind(schedule.organization_id,idem).first<{id:string}>();
      if(previous){await db.prepare("UPDATE school_fee_billing_schedules SET status='completed',last_batch_id=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(previous.id,schedule.id).run();continue}
      await db.prepare(`INSERT INTO school_fee_billing_batches (id,organization_id,batch_number,academic_year_id,term_id,structure_id,billing_date,due_date,criteria_json,status,total_students,idempotency_key,created_by) VALUES (?,?,?,?,?,?,?,?,?,'processing',?,?,'scheduler')`).bind(batchId,schedule.organization_id,batchNumber,schedule.academic_year_id,schedule.term_id,schedule.structure_id,schedule.run_on,schedule.due_date,schedule.criteria_json,students.results.length,idem).run();
      let billed=0,failed=0,total=0;const errors:any[]=[];for(const st of students.results){try{const r=await billStudent(db,schedule.organization_id,"scheduler",{studentId:st.id,academicYearId:schedule.academic_year_id,termId:schedule.term_id,structureId:schedule.structure_id,billingDate:schedule.run_on,dueDate:schedule.due_date,autoPost:Boolean(schedule.auto_post)},batchId,false);if(r.lines.some((x:any)=>x.status!=="skipped")){billed++;total+=r.totalMinor}}catch(e){failed++;errors.push({studentId:st.id,message:e instanceof Error?e.message:String(e)})}}
      const status=failed===0?"completed":billed?"partial":"failed";await db.batch([db.prepare("UPDATE school_fee_billing_batches SET status=?,billed_students=?,failed_students=?,total_amount_minor=?,errors_json=?,completed_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(status,billed,failed,total,JSON.stringify(errors.slice(0,500)),batchId),db.prepare("UPDATE school_fee_billing_schedules SET status=?,last_batch_id=?,last_error=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(status==="failed"?"failed":"completed",batchId,failed?`${failed} students failed billing`:null,schedule.id)]);
    }catch(error){await db.prepare("UPDATE school_fee_billing_schedules SET status='failed',last_error=?,updated_at=CURRENT_TIMESTAMP WHERE id=?").bind(error instanceof Error?error.message:String(error),schedule.id).run()}
  }
}
